#!/usr/bin/env bash
# Date de naissance d'un mineur, 3/3 — tests, doc, finitions.
# - e2e : demande au parent, date de majeur confirmée, passage majeur sur justificatif ;
# - doc dev, guides admin et membre ;
# - fiche admin : repart des données du serveur après un passage majeur ; textes du mineur au vouvoiement.
# Pas de migration. Prérequis : apply-date-naissance-2-front.sh.
# Usage (racine du repo) : bash apply-date-naissance-3-tests-doc.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"e2e/date-de-naissance-parent.spec.ts" 2>/dev/null | grep -qF "Date de naissance demandée au parent"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "markAdultWithProof" "apps/web/src/features/admin/users/legal/LegalStatusControl.tsx" 2>/dev/null || { echo "lancez d'abord apply-date-naissance-2-front.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/admin/droit-image-d-un-mineur.mdx" "apps/web/content/docs/admin/gerer-un-membre.mdx" "apps/web/content/docs/dev/legal/consentement-en-ligne.mdx" "apps/web/content/docs/guide/mon-profil.mdx" "apps/web/src/app/(admin)/dashboard/users/[id]/page.tsx" "apps/web/src/features/image-consent/AskGuardianBirthDate.tsx" "e2e/data.mjs" "e2e/droit-a-l-image-parent-pages.spec.ts" "e2e/droit-a-l-image-parent.spec.ts" "e2e/prepare.mjs" "packages/backend/src/modules/users/birthDateRequest.service.ts")
CREATED=("e2e/date-de-naissance-parent.spec.ts")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "Date de naissance demandée au parent" "e2e/date-de-naissance-parent.spec.ts" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "e2e"
